using FluentValidation;using NexHire.Application.DTOs.Auth;namespace NexHire.Application.Validators;public sealed class ResetPasswordRequestValidator:AbstractValidator<ResetPasswordRequestDto>{public ResetPasswordRequestValidator(){RuleFor(x=>x.Token).NotEmpty();RuleFor(x=>x.NewPassword).Must(PasswordPolicy.IsStrong).WithMessage("Password must contain uppercase, lowercase, number and symbol.");RuleFor(x=>x.ConfirmNewPassword).Equal(x=>x.NewPassword);}}
